104. ///
105. /// # Description
106. ///
107. /// A bounded cache using access-counter LRU approximation.
108. ///
109. /// Entries are stored in a `BTreeMap` keyed by `K`. A monotonic counter tracks access order;
110. /// on eviction the entry with the smallest (oldest) counter value is removed. Lookups bump the
111. /// counter to mark the entry as recently used.
112. ///
113. pub struct Cache<K, V> {
114.     /// Cached entries.
115.     entries: BTreeMap<K, CacheEntry<V>>,
116.     /// Monotonically increasing counter for LRU ordering.
117.     counter: u64,
118.     /// Maximum number of entries.
119.     capacity: usize,
120. }
121. 
122. impl<K: Ord + Clone, V> Cache<K, V> {
123.     ///
124.     /// # Description
125.     ///
126.     /// Creates a new empty cache with the given capacity.
127.     ///
128.     /// # Parameters
129.     ///
130.     /// - `capacity`: Maximum number of entries the cache can hold.
131.     ///
132.     pub const fn new(capacity: usize) -> Self {
133.         Self {
134.             entries: BTreeMap::new(),
135.             counter: 0,
136.             capacity,
137.         }
138.     }
139. 
140.     ///
141.     /// # Description
142.     ///
143.     /// Looks up a cached value and bumps its LRU counter on hit.
144.     ///
145.     /// # Parameters
146.     ///
147.     /// - `key`: The cache key to look up.
148.     ///
149.     /// # Returns
150.     ///
151.     /// An RAII guard providing access to the cached value, or `None` on cache miss.
152.     ///
153.     pub fn get(&mut self, key: &K) -> Option<CacheGuard<'_, V>> {
154.         if let Some(entry) = self.entries.get_mut(key) {
155.             self.counter += 1;
156.             entry.last_used = self.counter;
157.             Some(CacheGuard {
158.                 value: &mut entry.value,
159.             })
160.         } else {
161.             None
162.         }
163.     }
164. 
165.     ///
166.     /// # Description
167.     ///
168.     /// Inserts a value, evicting the least-recently-used entry if at capacity.
169.     ///
170.     /// # Parameters
171.     ///
172.     /// - `key`: The cache key to insert or update.
173.     /// - `value`: The value to store.
174.     ///
175.     pub fn put(&mut self, key: K, value: V) {
176.         // A zero-capacity cache cannot store entries.
177.         if self.capacity == 0 {
178.             return;
179.         }
180. 
181.         // If the key is already present, update in place.
182.         if let Some(entry) = self.entries.get_mut(&key) {
183.             self.counter += 1;
184.             entry.value = value;
185.             entry.last_used = self.counter;
186.             return;
187.         }
188. 
189.         // Evict the LRU entry if at capacity.
190.         if self.entries.len() >= self.capacity {
191.             self.evict();
192.         }
193. 
194.         self.counter += 1;
195.         self.entries.insert(
196.             key,
197.             CacheEntry {
198.                 value,
199.                 last_used: self.counter,
200.             },
201.         );
202.     }
203. 
204.     ///
205.     /// # Description
206.     ///
207.     /// Removes a specific key.
208.     ///
209.     /// # Parameters
210.     ///
211.     /// - `key`: The cache key to remove.
212.     ///
213.     pub fn remove(&mut self, key: &K) {
214.         self.entries.remove(key);
215.     }
216. 
217.     ///
218.     /// # Description
219.     ///
220.     /// Removes all entries.
221.     ///
222.     pub fn clear(&mut self) {
223.         self.entries.clear();
224.         self.counter = 0;
225.     }
226. 
227.     ///
228.     /// # Description
229.     ///
230.     /// Evicts the entry with the smallest `last_used` counter.
231.     ///
232.     fn evict(&mut self) {
233.         let victim: Option<K> = self
234.             .entries
235.             .iter()
236.             .min_by_key(|(_, e)| e.last_used)
237.             .map(|(k, _)| k.clone());
238.         if let Some(key) = victim {
239.             self.entries.remove(&key);
240.         }
241.     }
242. }
